export type ImageSlotType = 'face' | 'pose' | 'outer' | 'top' | 'bottom' | 'shoes' | 'accessory';

export interface ImageSlot {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
}

export interface GenerationResult {
  imageUrl: string;
  aspectRatio: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing. Please select your API key first.");
  return new GoogleGenAI({ apiKey });
};

/**
 * Analyzes an image using gemini-2.5-flash to get a concise description for styling.
 */
export async function analyzeImage(base64Data: string, type: string): Promise<string> {
  const ai = getAIClient();
  const mimeType = base64Data.split(';')[0].split(':')[1];
  const base64 = base64Data.split(',')[1];

  const prompt = `Describe this image for a fashion styling AI. Be concise but specific. 
  Focus on the clothing item's type, color, material, and distinctive details. 
  If it's a person, describe their pose and composition accurately.
  Reference type context: ${type}`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { mimeType, data: base64 } },
        { text: prompt }
      ]
    },
    config: {
      temperature: 0.2,
      topP: 0.8,
    }
  });

  return response.text || "No description generated.";
}

/**
 * Generates a fashion mix using gemini-3-pro-image-preview.
 */
export async function generateFashionMix(params: {
  faceImage?: string;
  poseImage?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
}): Promise<string> {
  const ai = getAIClient();

  const parts: any[] = [
    { text: `[System] You are an expert AI photo editor specializing in high-end fashion editorials. 
    Your goal is to create a seamless, high-resolution (2K) fashion image by combining specific references.

    **-- CRITICAL INSTRUCTIONS --**
    1. FACE IDENTITY: The subject's face, hair, and ethnicity MUST match the Face Reference image exactly.
    2. POSE: The body position, camera angle, and composition MUST match the Pose Reference image exactly. 
    3. CLOTHING: Dress the subject in the provided clothing items realistically, respecting their textures and fits.
    4. QUALITY: Photorealistic, 2K resolution, professional lighting, editorial aesthetic.` }
  ];

  if (params.faceImage) {
    parts.push({ text: "[Image Part 1] FACE/HAIR IDENTITY REFERENCE" });
    parts.push({
      inlineData: {
        mimeType: params.faceImage.split(';')[0].split(':')[1],
        data: params.faceImage.split(',')[1]
      }
    });
  }

  if (params.poseImage) {
    parts.push({ text: "[Image Part 2] POSE & BODY REFERENCE" });
    parts.push({
      inlineData: {
        mimeType: params.poseImage.split(';')[0].split(':')[1],
        data: params.poseImage.split(',')[1]
      }
    });
  }

  params.clothingImages.forEach((img, idx) => {
    parts.push({ text: `[Clothing Item ${idx + 1}] type: ${img.type}. Description: ${img.description}` });
    parts.push({
      inlineData: {
        mimeType: img.data.split(';')[0].split(':')[1],
        data: img.data.split(',')[1]
      }
    });
  });

  if (params.additionalPrompt) {
    parts.push({ text: `[Additional Creative Direction]: ${params.additionalPrompt}` });
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: {
      imageConfig: {
        aspectRatio: "9:16",
        imageSize: "2K"
      }
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image was generated by the model.");
}

import React from 'react';
import { ImageSlotType } from '../types';

interface ImageUploadProps {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
  onUpload: (id: ImageSlotType, file: File) => void;
}

const ImageUpload: React.FC<ImageUploadProps> = ({ id, label, data, description, isProcessing, onUpload }) => {
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onUpload(id, file);
    }
  };

  return (
    <div className="flex flex-col gap-2">
      <span className="text-xs font-semibold text-gray-400 uppercase tracking-wider">{label}</span>
      <label className={`
        relative flex flex-col items-center justify-center w-full aspect-[3/4] 
        rounded-xl border-2 border-dashed transition-all cursor-pointer
        ${data ? 'border-indigo-500/50 bg-indigo-500/5' : 'border-gray-800 hover:border-gray-700 bg-zinc-900/50'}
      `}>
        {data ? (
          <img src={data} alt={label} className="w-full h-full object-cover rounded-lg" />
        ) : (
          <div className="flex flex-col items-center gap-2 p-4 text-center">
            <svg className="w-8 h-8 text-gray-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 4v16m8-8H4" />
            </svg>
            <p className="text-[10px] text-gray-500">클릭하여 업로드하거나<br/>파일을 드래그하세요</p>
          </div>
        )}

        {isProcessing && (
          <div className="absolute inset-0 bg-black/60 flex items-center justify-center rounded-lg backdrop-blur-sm">
            <div className="flex flex-col items-center gap-2">
              <div className="w-5 h-5 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
              <span className="text-[10px] text-indigo-400 font-medium">분석 중...</span>
            </div>
          </div>
        )}

        <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
      </label>

      {description && !isProcessing && (
        <p className="text-[10px] text-gray-500 line-clamp-2 bg-zinc-900/50 p-1.5 rounded border border-gray-800">
          {description}
        </p>
      )}
    </div>
  );
};

export default ImageUpload;

import React, { useState, useEffect, useCallback } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

// Polyfills/Types for window.aistudio
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '액세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume success and proceed as per guidelines to avoid race condition
      setHasKey(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const base64 = await fileToBase64(file);

    // Update slot with data and set processing
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류가 발생했습니다.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }
    if (clothing.filter(c => c.data).length === 0) {
      setError("최소 한 개 이상의 의류 아이템이 필요합니다.");
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '9:16' });
    } catch (err: any) {
      console.error(err);
      if (err.message.includes("Requested entity was not found")) {
        setError("API 키 설정이 만료되었거나 잘못되었습니다. 다시 선택해주세요.");
        setHasKey(false);
      } else {
        setError(err.message || "이미지 생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 text-center">
        <div className="max-w-md w-full space-y-8 bg-zinc-900 p-10 rounded-3xl border border-zinc-800 shadow-2xl">
          <div className="space-y-4">
            <h1 className="text-3xl font-bold tracking-tight">AI Fashion Mix <span className="text-indigo-500">PRO</span></h1>
            <p className="text-gray-400 text-sm">
              이 애플리케이션은 Gemini 3 Pro (Nano Banana Pro) 모델을 사용합니다.<br/>
              계속하려면 결제가 활성화된 GCP 프로젝트의 API 키를 선택해야 합니다.
            </p>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener" className="inline-block text-xs text-indigo-400 hover:underline">
              결제 및 API 키 안내문서 보기
            </a>
          </div>
          <button
            onClick={handleSelectKey}
            className="w-full py-4 px-6 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-2xl transition-all shadow-[0_0_20px_rgba(79,70,229,0.3)]"
          >
            API 키 선택하기
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[1400px] mx-auto p-4 md:p-8 space-y-8">
      {/* Header */}
      <header className="text-center space-y-2">
        <h1 className="text-4xl font-extrabold tracking-tighter flex items-center justify-center gap-3">
          AI Fashion / Detailed Mix
          <span className="text-xs bg-indigo-600 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest align-middle">PRO</span>
        </h1>
        <p className="text-zinc-500 font-medium">
          Nano Banana Pro 모델로 얼굴/헤어와 포즈를 각각 지정하여 2K 고해상도 화보를 제작하세요.
        </p>
      </header>

      <main className="grid grid-cols-1 lg:grid-cols-[1fr_450px] gap-8 items-start">
        {/* Input Panel */}
        <section className="space-y-10">
          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">레퍼런스 영역</h2>
            <div className="grid grid-cols-2 gap-4">
              {slots.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">아이템/의류 이미지 <span className="text-xs font-normal text-zinc-500 ml-2">(하나 이상의 아이템을 업로드해주세요)</span></h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
              {clothing.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">프롬프트</h2>
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <textarea
                value={additionalPrompt}
                onChange={(e) => setAdditionalPrompt(e.target.value)}
                placeholder="예: '야외 카페의 화창한 날', '스튜디오 조명', '영화처럼', '비오는 거리'"
                className="w-full bg-transparent border-none focus:ring-0 text-gray-300 resize-none h-24"
              />
            </div>
          </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className={`
              w-full py-5 rounded-2xl font-bold text-lg flex items-center justify-center gap-3 transition-all
              ${isGenerating ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white shadow-xl shadow-indigo-500/20 active:scale-[0.98]'}
            `}
          >
            {isGenerating ? (
              <>
                <div className="w-5 h-5 border-2 border-zinc-500 border-t-transparent rounded-full animate-spin"></div>
                이미지 생성 중 (2K)...
              </>
            ) : (
              <>
                <span>✨</span> 이미지 생성 (2K)
              </>
            )}
          </button>
        </section>

        {/* Result Panel */}
        <aside className="sticky top-8 space-y-6">
          <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">결과 이미지</h2>
          <div className={`
            relative w-full aspect-[9/16] rounded-3xl border border-zinc-800 bg-zinc-900 overflow-hidden flex flex-col items-center justify-center text-center px-8
            ${isGenerating ? 'animate-pulse ring-2 ring-indigo-500/20' : ''}
          `}>
            {result ? (
              <div className="absolute inset-0 group">
                <img src={result.imageUrl} alt="Result" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                  <a
                    href={result.imageUrl}
                    download="fashion-editorial-2k.png"
                    className="bg-white text-black px-6 py-2 rounded-full font-bold hover:bg-zinc-200 transition-colors"
                  >
                    다운로드 (2K)
                  </a>
                </div>
              </div>
            ) : (
              <div className="space-y-4">
                {isGenerating ? (
                  <div className="space-y-4">
                    <p className="text-xl font-bold text-indigo-400">화보 제작 중...</p>
                    <p className="text-sm text-gray-500 max-w-xs mx-auto">
                      고해상도 2K 이미지를 생성하고 있습니다. 잠시만 기다려 주세요. 
                      모델이 의류를 피팅하고 조명을 조절하는 데 약 20-40초가 소요됩니다.
                    </p>
                  </div>
                ) : (
                  <>
                    <div className="w-16 h-16 bg-zinc-800 rounded-2xl flex items-center justify-center mx-auto mb-2">
                      <svg className="w-8 h-8 text-zinc-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                    </div>
                    <h3 className="text-lg font-bold text-gray-400">결과물을 기다리고 있어요</h3>
                    <p className="text-xs text-zinc-500">
                      이미지를 업로드하고 옵션을 설정하여 마법같은 결과물을 확인하세요.
                    </p>
                  </>
                )}
              </div>
            )}
          </div>

          {error && (
            <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-medium">
              {error}
            </div>
          )}

          {/* Guidelines */}
          <div className="bg-zinc-900/50 p-6 rounded-2xl border border-zinc-800 space-y-4">
            <h4 className="text-xs font-bold uppercase tracking-widest text-zinc-500">이미지 업로드 가이드라인</h4>
            <ul className="text-[11px] text-zinc-500 space-y-3 leading-relaxed">
              <li>
                <strong className="text-zinc-400 block mb-0.5">최상의 결과물을 위한 팁</strong>
                인물 사진과 비슷한 구도의 의류 이미지를 사용하면, AI가 옷을 합성하는 과정에서 얼굴과 신체를 왜곡 없이 자연스럽게 합성하는 데 도움이 됩니다.
              </li>
              <li>
                <strong className="text-zinc-400 block mb-0.5">얼굴이 변경되는 현상에 대하여</strong>
                AI가 옷을 합성하는 과정에서 얼굴이 미세하게 바뀔 수 있습니다. 이 문제를 해결하기 위해 저희는 AI가 원본 얼굴을 절대 변경하지 않도록 시스템을 업데이트하여 결과의 정확도를 높였습니다.
              </li>
            </ul>
          </div>
        </aside>
      </main>
    </div>
  );
}

import React, { useState, useEffect, useCallback } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

// Polyfills/Types for window.aistudio
declare global {
  // Use declaration merging to define the AIStudio type
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  // The 'aistudio' property is already defined on Window as AIStudio in the environment.
  // We don't need to redeclare it here to avoid modifier and type conflicts.
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '액세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume success and proceed as per guidelines to avoid race condition
      setHasKey(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const base64 = await fileToBase64(file);

    // Update slot with data and set processing
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류가 발생했습니다.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }
    if (clothing.filter(c => c.data).length === 0) {
      setError("최소 한 개 이상의 의류 아이템이 필요합니다.");
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '9:16' });
    } catch (err: any) {
      console.error(err);
      // Handle the case where the API key is invalid or not found
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("API 키 설정이 만료되었거나 잘못되었습니다. 다시 선택해주세요.");
        setHasKey(false);
      } else {
        setError(err.message || "이미지 생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 text-center">
        <div className="max-w-md w-full space-y-8 bg-zinc-900 p-10 rounded-3xl border border-zinc-800 shadow-2xl">
          <div className="space-y-4">
            <h1 className="text-3xl font-bold tracking-tight">AI Fashion Mix <span className="text-indigo-500">PRO</span></h1>
            <p className="text-gray-400 text-sm">
              이 애플리케이션은 Gemini 3 Pro (Nano Banana Pro) 모델을 사용합니다.<br/>
              계속하려면 결제가 활성화된 GCP 프로젝트의 API 키를 선택해야 합니다.
            </p>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" rel="noopener" className="inline-block text-xs text-indigo-400 hover:underline">
              결제 및 API 키 안내문서 보기
            </a>
          </div>
          <button
            onClick={handleSelectKey}
            className="w-full py-4 px-6 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-2xl transition-all shadow-[0_0_20px_rgba(79,70,229,0.3)]"
          >
            API 키 선택하기
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[1400px] mx-auto p-4 md:p-8 space-y-8">
      {/* Header */}
      <header className="text-center space-y-2">
        <h1 className="text-4xl font-extrabold tracking-tighter flex items-center justify-center gap-3">
          AI Fashion / Detailed Mix
          <span className="text-xs bg-indigo-600 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest align-middle">PRO</span>
        </h1>
        <p className="text-zinc-500 font-medium">
          Nano Banana Pro 모델로 얼굴/헤어와 포즈를 각각 지정하여 2K 고해상도 화보를 제작하세요.
        </p>
      </header>

      <main className="grid grid-cols-1 lg:grid-cols-[1fr_450px] gap-8 items-start">
        {/* Input Panel */}
        <section className="space-y-10">
          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">레퍼런스 영역</h2>
            <div className="grid grid-cols-2 gap-4">
              {slots.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">아이템/의류 이미지 <span className="text-xs font-normal text-zinc-500 ml-2">(하나 이상의 아이템을 업로드해주세요)</span></h2>
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
              {clothing.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-lg font-bold border-l-4 border-indigo-500 pl-3">프롬프트</h2>
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <textarea
                value={additionalPrompt}
                onChange={(e) => setAdditionalPrompt(e.target.value)}
                placeholder="예: '야외 카페의 화창한 날', '스튜디오 조명', '영화처럼', '비오는 거리'"
                className="w-full bg-transparent border-none focus:ring-0 text-gray-300 resize-none h-24"
              />
            </div>
          </div>

          <button
            onClick={handleGenerate}
            disabled={isGenerating}
            className={`
              w-full py-5 rounded-2xl font-bold text-lg flex items-center justify-center gap-3 transition-all
              ${isGenerating ? 'bg-zinc-800 text-zinc-500 cursor-not-allowed' : 'bg-gradient-to-r from-indigo-600 to-violet-600 hover:from-indigo-500 hover:to-violet-500 text-white shadow-xl shadow-indigo-500/20 active:scale-[0.98]'}
            `}
          >
            {isGenerating ? (
