import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasKey(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류가 발생했습니다.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }
    if (clothing.filter(c => c.data).length === 0) {
      setError("최소 한 개 이상의 의류 아이템이 필요합니다.");
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '9:16' });
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("API 키 설정이 만료되었거나 잘못되었습니다. 다시 선택해주세요.");
        setHasKey(false);
      } else {
        setError(err.message || "이미지 생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 text-center bg-black">
        <div className="max-w-md w-full space-y-8 bg-zinc-900 p-10 rounded-3xl border border-zinc-800 shadow-2xl">
          <div className="space-y-4">
            <h1 className="text-3xl font-bold tracking-tight text-white">AI Fashion Mix <span className="text-indigo-500">PRO</span></h1>
            <p className="text-zinc-400 text-sm">
              이 애플리케이션은 Gemini 3 Pro 모델을 사용합니다.<br/>
              결제가 활성화된 프로젝트의 API 키를 선택해주세요.
            </p>
          </div>
          <button
            onClick={handleSelectKey}
            className="w-full py-4 px-6 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-2xl transition-all"
          >
            API 키 선택하기
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-[1600px] mx-auto p-6 md:p-12 space-y-12">
      {/* Header */}
      <header className="text-center space-y-3">
        <h1 className="text-5xl font-black tracking-tighter flex items-center justify-center gap-4 text-white">
          AI Fashion / Detailed Mix
          <span className="text-sm bg-indigo-600 px-3 py-1 rounded-full font-bold uppercase tracking-widest align-middle">PRO</span>
        </h1>
        <p className="text-zinc-500 font-medium text-lg">
          Nano Banana Pro 모델로 얼굴/헤어와 포즈를 각각 지정하여 2K 고해상도 화보를 제작하세요.
        </p>
      </header>

      {/* Main Grid: Top Row with References and Result */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        {slots.map(slot => (
          <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
        ))}

        {/* Result Area */}
        <div className="flex flex-col gap-2 w-full">
          <span className="text-sm font-bold text-white text-center mb-1">결과 이미지</span>
          <div className={`
            relative w-full aspect-[2/3] rounded-xl border-2 border-dashed bg-black overflow-hidden flex flex-col items-center justify-center text-center px-8
            ${isGenerating ? 'border-indigo-500 ring-4 ring-indigo-500/10' : 'border-zinc-800'}
          `}>
            {result ? (
              <div className="absolute inset-0 group">
                <img src={result.imageUrl} alt="Result" className="w-full h-full object-cover" />
                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-4">
                  <span className="text-white font-bold text-xl drop-shadow-lg">2K Resolution</span>
                  <a
                    href={result.imageUrl}
                    download="fashion-2k.png"
                    className="bg-indigo-600 text-white px-8 py-3 rounded-full font-bold hover:bg-indigo-500 transition-all shadow-xl"
                  >
                    이미지 다운로드
                  </a>
                </div>
              </div>
            ) : (
              <div className="space-y-6">
                {isGenerating ? (
                  <div className="space-y-4 flex flex-col items-center">
                    <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
                    <div className="space-y-2">
                      <p className="text-xl font-bold text-white">화보 제작 중...</p>
                      <p className="text-xs text-zinc-500 max-w-xs mx-auto leading-relaxed">
                        고해상도 2K 이미지를 생성하고 있습니다.<br/>모델 구동에 약 30초가 소요됩니다.
                      </p>
                    </div>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <h3 className="text-xl font-bold text-zinc-400">결과물을 기다리고 있어요</h3>
                    <p className="text-sm text-zinc-500">
                      이미지를 업로드하고 옵션을 설정하여<br/>마법같은 결과물을 확인하세요.
                    </p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
