import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasKey(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }
    if (clothing.filter(c => c.data).length === 0) {
      setError("최소 한 개 이상의 의류 아이템이 필요합니다.");
      return;
    }

    setIsGenerating(true);
    setError(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '9:16' });
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("API 키를 다시 선택해주세요.");
        setHasKey(false);
      } else {
        setError(err.message || "이미지 생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 text-center bg-black">
        <div className="max-w-md w-full space-y-8 bg-zinc-900 p-10 rounded-3xl border border-zinc-800">
          <h1 className="text-2xl font-bold">AI Fashion Mix <span className="text-indigo-500">PRO</span></h1>
          <button
            onClick={handleSelectKey}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-2xl transition-all"
          >
            API 키 선택하기
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white font-['Inter']">
      {/* Header */}
      <header className="p-6 border-b border-zinc-900">
        <div className="max-w-[1800px] mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-black tracking-tighter">AI Fashion / Detailed Mix</h1>
            <span className="text-[10px] bg-indigo-600 px-2 py-0.5 rounded-full font-bold uppercase tracking-widest">PRO</span>
          </div>
          <p className="text-zinc-500 text-sm hidden md:block">Nano Banana Pro 2K 화보 제작 툴</p>
        </div>
      </header>

      {/* Main Container - Left/Right Split */}
      <main className="max-w-[1800px] mx-auto grid grid-cols-1 lg:grid-cols-2 min-h-[calc(100vh-80px)]">

        {/* Left Section: Inputs */}
        <section className="p-6 lg:p-10 border-r border-zinc-900 space-y-10 overflow-y-auto max-h-[calc(100vh-80px)]">

          {/* Reference Row */}
          <div className="space-y-4">
            <h2 className="text-sm font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></span>
              레퍼런스 영역
            </h2>
            <div className="grid grid-cols-2 gap-4">
              {slots.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          {/* Clothing Items Grid - 2 Rows */}
          <div className="space-y-4">
            <h2 className="text-sm font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
              <span className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></span>
              아이템/의류 이미지
            </h2>
            <div className="grid grid-cols-3 gap-4">
              {/* This naturally creates 2 rows (3 items in row 1, 2 items in row 2) */}
              {clothing.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          {/* Prompt & Action */}
          <div className="space-y-6 pt-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-zinc-500 uppercase tracking-widest">추가 프롬프트</label>
              <div className="bg-zinc-900/50 border border-zinc-800 rounded-xl p-4 focus-within:border-indigo-500/50 transition-colors">
                <textarea
                  value={additionalPrompt}
                  onChange={(e) => setAdditionalPrompt(e.target.value)}
                  placeholder="분위기, 배경, 조명 등 세부 지시 사항을 입력하세요..."
                  className="w-full bg-transparent border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-700 resize-none h-20 text-sm"
                />
              </div>
            </div>

            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              className={`
                w-full py-5 rounded-xl font-black text-lg flex items-center justify-center gap-3 transition-all
                ${isGenerating ? 'bg-zinc-800 text-zinc-600 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-[0_0_30px_rgba(79,70,229,0.2)] active:scale-[0.98]'}
              `}
            >
              {isGenerating ? (
                <>
                  <div className="w-5 h-5 border-2 border-zinc-600 border-t-transparent rounded-full animate-spin"></div>
                  생성 중...
                </>
              ) : (
                <><span>✨</span> 이미지 생성 (2K)</>
              )}
            </button>

            {error && (
              <div className="p-4 bg-red-500/10 border border-red-500/20 rounded-xl text-red-400 text-xs font-semibold">
                ⚠️ {error}
              </div>
            )}
          </div>
        </section>

        {/* Right Section: Result */}
        <section className="bg-zinc-950 p-6 lg:p-10 flex flex-col items-center justify-center">
          <div className="w-full max-w-[500px] flex flex-col gap-4">
            <h2 className="text-sm font-black text-zinc-500 uppercase tracking-widest text-center">최종 결과 이미지 (2K)</h2>

            <div className={`
              relative w-full aspect-[9/16] rounded-2xl border border-zinc-800 bg-black overflow-hidden flex flex-col items-center justify-center
              ${isGenerating ? 'ring-2 ring-indigo-500/30' : ''}
            `}>
              {result ? (
                <div className="absolute inset-0 group">
                  <img src={result.imageUrl} alt="Final" className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center gap-4">
                    <a
                      href={result.imageUrl}
                      download="fashion-editorial.png"
                      className="bg-white text-black px-8 py-3 rounded-full font-bold hover:bg-zinc-200 transition-all shadow-xl"
                    >
                      고해상도 다운로드
                    </a>
                  </div>
                </div>
              ) : (
                <div className="p-12 text-center space-y-4">
                  {isGenerating ? (
                    <div className="space-y-3">
                      <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
                      <p className="text-zinc-400 font-bold animate-pulse">화보를 렌더링하고 있습니다...</p>
                      <p className="text-[10px] text-zinc-600">고해상도(2K) 처리를 위해 약 30초가 소요됩니다.</p>
                    </div>
                  ) : (
                    <div className="space-y-2 opacity-30">
                      <svg className="w-16 h-16 text-zinc-700 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                      <p className="text-sm font-medium">생성된 이미지가 이곳에 표시됩니다</p>
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Guide Text in Right Column */}
            <div className="mt-8 pt-8 border-t border-zinc-900 space-y-4">
              <h4 className="text-[10px] font-black uppercase text-zinc-700 tracking-widest">사용 팁</h4>
              <p className="text-[11px] text-zinc-600 leading-relaxed">
                레퍼런스 이미지와 생성하고자 하는 의류의 구도가 유사할수록 AI가 신체 구조를 더욱 정확하게 파악하여 자연스러운 결과물을 만들어냅니다.
              </p>
            </div>
          </div>
        </section>

      </main>
    </div>
  );
