import React, { useState } from 'react';
import { ImageSlotType } from '../types';

interface ImageUploadProps {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
  onUpload: (id: ImageSlotType, file: File) => void;
}

const ImageUpload: React.FC<ImageUploadProps> = ({ id, label, data, description, isProcessing, onUpload }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onUpload(id, file);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = () => {
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      onUpload(id, file);
    }
  };

  return (
    <div className="flex flex-col gap-2 w-full">
      <span className="text-xs font-bold text-[#ffffff] uppercase tracking-normal">{label}</span>
      <label 
        className={`
          relative flex flex-col items-center justify-center w-full aspect-square
          rounded-xl border-2 border-dashed transition-all cursor-pointer overflow-hidden
          ${data ? 'border-indigo-500 bg-black' : 'border-zinc-800 bg-black'}
          ${isDragging ? 'border-indigo-400 bg-indigo-500/10 scale-[1.02]' : 'hover:border-indigo-500/50'}
        `}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
      >
        {data ? (
          <img src={data} alt={label} className="w-full h-full object-cover" />
        ) : (
          <div className="flex flex-col items-center gap-2 p-2 text-center pointer-events-none">
            <svg className={`w-6 h-6 ${isDragging ? 'text-indigo-400' : 'text-zinc-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 4v16m8-8H4" />
            </svg>
            <div className="space-y-0.5">
              <p className="text-[10px] text-indigo-400 font-medium underline">업로드</p>
              <p className="text-[9px] text-zinc-600 hidden sm:block">드래그하거나 클릭</p>
            </div>
          </div>
        )}

        {isProcessing && (
          <div className="absolute inset-0 bg-black/80 flex items-center justify-center backdrop-blur-sm">
            <div className="flex flex-col items-center gap-1">
              <div className="w-4 h-4 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
              <span className="text-[9px] text-indigo-400 font-semibold tracking-tighter">분석중</span>
            </div>
          </div>
        )}

        <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
      </label>

      {description && !isProcessing && (
        <div className="text-[9px] text-zinc-500 line-clamp-1 bg-zinc-900/40 px-1 py-0.5 rounded italic">
          {description}
        </div>
      )}
    </div>
  );
};

