import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPrompt } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [hasKey, setHasKey] = useState<boolean>(false);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasKey(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // 선택 후 즉시 앱 진입 (race condition 방지)
      setHasKey(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }
    if (clothing.filter(c => c.data).length === 0) {
      setError("최소 한 개 이상의 의류 아이템이 필요합니다.");
      return;
    }

    setIsGenerating(true);
    setError(null);
    setMjPrompt(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const [imageUrl, prompts] = await Promise.all([
        generateFashionMix({
          faceImage,
          poseImage,
          clothingImages,
          additionalPrompt
        }),
        generateMidjourneyPrompt({
          descriptions: [
            ...slots.filter(s => s.data).map(s => ({ type: s.label, text: s.description })),
            ...clothing.filter(c => c.data).map(c => ({ type: c.label, text: c.description }))
          ],
          additionalPrompt
        })
      ]);

      setResult({ imageUrl, aspectRatio: '9:16' });
      setMjPrompt(prompts);
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("API 키를 다시 선택해주세요.");
        setHasKey(false);
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  if (!hasKey) {
    return (
      <div className="min-h-screen flex items-center justify-center p-6 bg-black text-white">
        <div className="max-w-[480px] w-full p-12 rounded-[2rem] bg-zinc-950 border border-zinc-900 shadow-2xl space-y-8 text-center">
          <div className="space-y-3">
            <h1 className="text-3xl font-black text-white tracking-tight">AI Fashion Mix <span className="text-indigo-500">PRO</span></h1>
            <p className="text-zinc-500 text-sm font-medium">Nano Banana Pro 2K & Gemini 3 Pro를 사용하려면<br/>유료 API 키를 선택해야 합니다.</p>
          </div>

          <button
            onClick={handleSelectKey}
            className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl transition-all shadow-lg shadow-indigo-500/20 active:scale-[0.98]"
          >
            API 키 선택하기
          </button>

          <div className="pt-4">
            <a 
              href="https://ai.google.dev/gemini-api/docs/billing" 
              target="_blank" 
              rel="noopener noreferrer"
              className="text-[10px] text-zinc-600 hover:text-indigo-400 transition-colors underline underline-offset-4 uppercase tracking-widest font-bold"
            >
              결제 및 API 가이드 확인하기
            </a>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white font-['Inter'] flex flex-col">
      {/* Header */}
      <header className="py-10 px-6 bg-black border-b border-zinc-900/50">
        <div className="max-w-[1800px] mx-auto text-center space-y-2">
          <div className="inline-flex items-center gap-3">
            <h1 className="text-[32px] font-black tracking-tight leading-none text-white">AI Fashion / Detailed Mix</h1>
            <span className="text-[10px] bg-indigo-600 px-2.5 py-1 rounded-full font-black uppercase tracking-wider text-white">PRO</span>
          </div>
          <p className="text-zinc-500 text-[14px] font-semibold tracking-wide uppercase opacity-70">Editorial Compositing: Gemini 3 Pro & Nano Banana 2K</p>
        </div>
      </header>

      {/* Main Container */}
      <main className="max-w-[1800px] mx-auto grid grid-cols-1 lg:grid-cols-2 flex-grow overflow-hidden">

        {/* Left Section: Inputs - Scrollbar Hidden */}
        <section className="p-6 lg:p-10 space-y-12 overflow-y-auto max-h-[calc(100vh-140px)] scrollbar-hide border-r border-zinc-900/50">

          {/* Reference Row */}
          <div className="space-y-6">
            <h2 className="text-[16px] font-black text-[#ffffff] uppercase tracking-normal">레퍼런스 영역</h2>
            <div className="grid grid-cols-2 gap-8">
              {slots.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          {/* Clothing Items Grid */}
          <div className="space-y-6">
            <h2 className="text-[16px] font-black text-[#ffffff] uppercase tracking-normal">아이템/의류 이미지</h2>
            <div className="grid grid-cols-3 gap-6">
              {clothing.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          {/* Prompt & Action */}
          <div className="space-y-6 pt-6 border-t border-zinc-900/30">
            <div className="space-y-2">
              <label className="text-[16px] font-bold text-[#ffffff] uppercase tracking-normal">추가 프롬프트</label>
              <div className="bg-zinc-950 border border-zinc-900 rounded-2xl p-5 focus-within:border-indigo-500/40 transition-all shadow-inner">
                <textarea
                  value={additionalPrompt}
                  onChange={(e) => setAdditionalPrompt(e.target.value)}
                  placeholder="분위기, 배경, 조명 등 세부 지시 사항을 입력하세요..."
                  className="w-full bg-transparent border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-800 resize-none h-28 text-sm tracking-normal leading-relaxed"
                />
              </div>
            </div>

            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              style={{ backgroundColor: isGenerating ? '#19ad55' : '#242b35' }}
              className={`
                w-full py-6 rounded-2xl font-black text-xl flex items-center justify-center gap-3 transition-all tracking-tight shadow-xl text-white
                ${isGenerating ? 'cursor-not-allowed' : 'hover:opacity-90 active:scale-[0.99]'}
              `}
            >
              {isGenerating ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  GENERATING 2K...
                </>
              ) : (
                <>Generate Image(2K)</>
              )}
            </button>

            {error && (
              <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl text-red-400 text-[11px] font-bold tracking-normal text-center">
                ⚠️ {error}
              </div>
