          </div>
        </section>

        {/* Right Section: Result - Scrollbar Hidden */}
        <section className="bg-black p-6 lg:p-10 flex flex-col items-center justify-start overflow-y-auto max-h-[calc(100vh-140px)] scrollbar-hide">
          <div className="w-full max-w-[600px] flex flex-col gap-6 pb-20">
