      setMjPrompt(prompts);
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("유료 API 키를 다시 선택해주세요.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="h-screen bg-black text-white font-['Inter'] flex flex-col overflow-hidden">
      {/* Header */}
      <header className="py-8 px-6 bg-black border-b border-zinc-900/50 flex-shrink-0">
