interface ImageUploadProps {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
  onUpload: (id: ImageSlotType, file: File) => void;
}

const ImageUpload: React.FC<ImageUploadProps> = ({ id, label, data, description, isProcessing, onUpload }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      onUpload(id, file);
    }
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const onDragLeave = () => {
    setIsDragging(false);
  };

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files?.[0];
    if (file && file.type.startsWith('image/')) {
      onUpload(id, file);
    }
  };

  const getRecommendedText = () => {
    if (id === 'face') return 'RECOMMENDED: PORTRAIT IDENTITY SHOT';
    if (id === 'pose') return 'RECOMMENDED: FULL BODY POSE';
