          ${data ? 'border-indigo-500 bg-zinc-950' : 'border-zinc-800 bg-black'}
          ${isDragging ? 'border-indigo-400 bg-indigo-500/10 scale-[1.02]' : 'hover:border-zinc-700'}
        `}
        onDragOver={onDragOver}
        onDragLeave={onDragLeave}
        onDrop={onDrop}
      >
        {data ? (
          <img src={data} alt={label} className="w-full h-full object-contain bg-zinc-950" />
        ) : (
          <div className="flex flex-col items-center text-center pointer-events-none p-10">
            <div className={`w-9 h-9 rounded-full bg-zinc-900/60 flex items-center justify-center mb-4 transition-colors ${isDragging ? 'bg-indigo-900/40' : ''}`}>
               <svg className={`w-5 h-5 ${isDragging ? 'text-indigo-400' : 'text-zinc-500'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6v12m6-6H6" />
              </svg>
            </div>
            <div className="space-y-1.5">
              <p className="text-[9px] text-zinc-400 font-bold uppercase tracking-[0.15em]">UPLOAD OR DRAG IMAGE</p>
              <p className="text-[7px] text-zinc-600 font-semibold uppercase tracking-wider">{getRecommendedText()}</p>
            </div>
          </div>
        )}

        {isProcessing && (
          <div className="absolute inset-0 bg-black/80 flex items-center justify-center backdrop-blur-sm">
            <div className="flex flex-col items-center gap-1">
              <div className="w-4 h-4 border border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
              <span className="text-[8px] text-indigo-400 font-bold tracking-widest mt-2">ANALYZING</span>
            </div>
          </div>
        )}

        <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
      </label>

      {description && !isProcessing && (
        <div className="text-[8px] text-zinc-600 line-clamp-1 bg-zinc-900/20 px-1 py-0.5 rounded italic">
          {description}
        </div>
      )}
    </div>
  );
};

