import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPrompt } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(true);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }

    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생. API 키 설정을 확인하세요.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }

    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setMjPrompt(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const [imageUrl, prompts] = await Promise.all([
        generateFashionMix({
          faceImage,
          poseImage,
          clothingImages,
          additionalPrompt
        }),
        generateMidjourneyPrompt({
          descriptions: [
            ...slots.filter(s => s.data).map(s => ({ type: s.label, text: s.description })),
            ...clothing.filter(c => c.data).map(c => ({ type: c.label, text: c.description }))
          ],
          additionalPrompt
        })
      ]);

      setResult({ imageUrl, aspectRatio: '9:16' });
      setMjPrompt(prompts);

      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("유료 API 키가 필요합니다. 다시 선택해주세요.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
    }
  };

  const isReadyToGenerate = !!slots.find(s => s.id === 'face')?.data;

  return (
    <div className="min-h-screen bg-black text-white font-['Inter'] flex flex-col">
      {/* Header - Centered Title, Medium Font Weight */}
      <header className="py-10 px-6 bg-black border-b border-zinc-900/50 flex-shrink-0">
        <div className="max-w-[1800px] mx-auto flex flex-col items-center text-center">
          <div className="inline-flex items-center gap-3">
            <h1 className="text-[32px] font-medium tracking-tight leading-none">AI Fashion / Detailed Mix</h1>
            <span className="text-[10px] bg-indigo-600 px-2.5 py-1 rounded-full font-black uppercase tracking-wider">PRO</span>
          </div>
          <p className="text-zinc-600 text-[13px] font-bold uppercase tracking-widest mt-2 opacity-80">Studio Editorial Synthesis Engine</p>
        </div>
      </header>

      {/* Main Container - Integrated Scroll */}
      <main className="max-w-[1800px] mx-auto grid grid-cols-1 lg:grid-cols-2 flex-grow w-full">

        {/* Left Section: Inputs */}
        <section className="p-6 lg:p-10 space-y-12 border-r border-zinc-900/50">

          <div className="space-y-6">
            <h2 className="text-[14px] font-black text-zinc-500 uppercase tracking-[0.2em]">레퍼런스 이미지</h2>
            <div className="grid grid-cols-2 gap-8">
              {slots.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <h2 className="text-[14px] font-black text-zinc-500 uppercase tracking-[0.2em]">의상 / 아이템</h2>
            <div className="grid grid-cols-3 gap-6">
              {clothing.map(slot => (
                <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} />
              ))}
            </div>
          </div>

          <div className="space-y-6 pt-6 border-t border-zinc-900/30">
            <div className="space-y-2">
              <label className="text-[14px] font-bold text-zinc-500 uppercase tracking-widest">Prompt 추가</label>
              <div className="bg-zinc-950 border border-zinc-900 rounded-2xl p-5 focus-within:border-zinc-700 transition-all">
                <textarea
                  value={additionalPrompt}
                  onChange={(e) => setAdditionalPrompt(e.target.value)}
                  placeholder="분위기, 배경, 조명 등 세부 지시 사항을 입력하세요..."
                  className="w-full bg-transparent border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-800 resize-none h-24 text-sm tracking-normal leading-relaxed"
                />
              </div>
            </div>

            <button
              onClick={handleGenerate}
              disabled={isGenerating}
              style={{ 
                backgroundColor: (isGenerating || isReadyToGenerate) ? '#19ad55' : '#242b35',
                fontSize: '16px',
                letterSpacing: 'normal'
              }}
              className={`
                w-full py-6 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl text-white
                ${isGenerating ? 'cursor-not-allowed' : 'hover:opacity-90 active:scale-[0.99]'}
              `}
            >
              {isGenerating ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  GENERATING 2K...
                </>
              ) : (
                <>Generate Image(2K)</>
              )}
            </button>

            {error && (
              <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl text-red-400 text-[11px] font-bold tracking-normal text-center">
                ⚠️ {error}
              </div>
            )}
          </div>
        </section>

        {/* Right Section: Result */}
        <section className="bg-black p-6 lg:p-10 flex flex-col items-center justify-start">
          <div className="w-full max-w-[600px] flex flex-col gap-6 pb-20">
            <h2 className="text-[14px] font-black text-zinc-500 uppercase tracking-[0.2em]">최종 이미지(2K)</h2>

            <div className={`
              relative w-full aspect-[9/16] rounded-3xl border border-zinc-900 bg-zinc-950 overflow-hidden flex flex-col items-center justify-center shadow-2xl
              ${isGenerating ? 'ring-2 ring-[#19ad55]/20' : ''}
            `}>
              {result ? (
                <div className="absolute inset-0 group bg-zinc-950">
                  <img src={result.imageUrl} alt="Final" className="w-full h-full object-contain" />
                  <div className="absolute inset-0 bg-black/70 opacity-0 group-hover:opacity-100 transition-all duration-300 flex flex-col items-center justify-center gap-6 backdrop-blur-sm">
                    <a
                      href={result.imageUrl}
                      download="fashion-editorial-2k.png"
                      className="bg-white text-black px-10 py-4 rounded-full font-black text-sm uppercase tracking-widest hover:bg-[#19ad55] hover:text-white transition-all shadow-2xl active:scale-[0.95]"
                    >
                      Download 2K Image
                    </a>
                  </div>
                </div>
              ) : (
                <div className="p-16 text-center space-y-6">
                  {isGenerating ? (
                    <div className="space-y-4">
                      <div className="w-10 h-10 border-2 border-[#19ad55] border-t-transparent rounded-full animate-spin mx-auto"></div>
                      <div className="space-y-1">
                        <p className="text-[#19ad55] text-sm font-black animate-pulse tracking-widest uppercase">Rendering High-Fidelity</p>
                        <p className="text-[10px] text-zinc-700 tracking-wider uppercase font-bold">Nano Banana Pro Image Engine</p>
                      </div>
                    </div>
                  ) : (
                    <div className="space-y-4 opacity-10">
                      <svg className="w-20 h-20 text-zinc-500 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                      </svg>
                      <p className="text-[12px] font-black text-zinc-500 tracking-[0.2em] uppercase">Studio Output Ready</p>
                    </div>
                  )}
                </div>
              )}
            </div>

            {mjPrompt && (
              <div className="space-y-6 p-8 bg-zinc-950/50 border border-zinc-900 rounded-[2rem] shadow-xl">
                <div className="flex items-center justify-between border-b border-zinc-900 pb-4">
                  <div className="flex flex-col">
                    <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Midjourney V7 Prompt</h3>
                    <span className="text-[13px] font-black text-zinc-400 uppercase tracking-tight">Structured Editorial</span>
                  </div>
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(mjPrompt.positive);
                    }}
                    className="text-[10px] bg-zinc-900 hover:bg-zinc-800 px-4 py-2 rounded-xl text-zinc-400 font-bold uppercase transition-all active:scale-[0.95] border border-zinc-800"
                  >
                    Copy
                  </button>
                </div>
                <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-zinc-600 uppercase block mb-3 tracking-[0.15em]">Positive Prompt</label>
                    <p className="text-[11px] text-zinc-400 font-mono leading-relaxed bg-black p-4 rounded-2xl border border-zinc-900/50">
                      {mjPrompt.positive}
                    </p>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-red-900/40 uppercase block mb-3 tracking-[0.15em]">Negative Prompt</label>
                    <p className="text-[11px] text-red-950/50 font-mono leading-relaxed bg-black/40 p-4 rounded-2xl border border-red-950/10">
                      {mjPrompt.negative}
                    </p>
                  </div>
                </div>
              </div>
            )}

            <div className="mt-4 pt-8 border-t border-zinc-900/40 space-y-4">
              <h4 className="text-[11px] font-black uppercase text-zinc-600 tracking-widest">Generation Protocol</h4>
              <p className="text-[10.5px] text-zinc-700 leading-relaxed tracking-normal font-medium">
                Identity preservation logic maintains face & hair characteristics. Anatomical posing strictly follows the pose reference.
              </p>
            </div>
          </div>
        </section>

      </main>
    </div>
  );
