import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing. Please select your API key first.");
  return new GoogleGenAI({ apiKey });
};

/**
 * Analyzes an image using gemini-3-flash to get a concise description for styling.
 */
export async function analyzeImage(base64Data: string, type: string): Promise<string> {
  const ai = getAIClient();
  const mimeType = base64Data.split(';')[0].split(':')[1];
  const base64 = base64Data.split(',')[1];

  const prompt = `Describe this fashion item or person reference for a high-end AI styling engine.
  Focus on:
  - Material textures (silk, wool, leather, etc.)
  - Precise colors and patterns
  - Fit and drape
  - Distinctive hardware or details
  Reference type: ${type}`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { mimeType, data: base64 } },
        { text: prompt }
      ]
    },
    config: {
      temperature: 0.1,
    }
  });

  return response.text || "No description.";
}

/**
 * Analyzes the FINAL generated image using Gemini 3 Pro to create a highly accurate Midjourney V7 prompt.
 */
export async function generateMidjourneyPromptFromImage(imageUrl: string): Promise<{ positive: string, negative: string }> {
  const ai = getAIClient();
  const mimeType = imageUrl.split(';')[0].split(':')[1];
  const base64 = imageUrl.split(',')[1];

  const prompt = `Act as a world-class Midjourney Prompt Engineer. 
  Analyze this generated fashion editorial image in detail and create a perfect Midjourney V7 prompt that would reproduce its exact aesthetic.

  The Positive Prompt MUST follow this strict sequence:
  1. [Subject]: Detailed description of the model, clothing, fabrics, and posture.
  2. [Style]: Artistic aesthetic, lighting type (e.g., hard shadows, soft box), and photographic style (e.g., high-end editorial).
  3. [Background]: Environment, props, and setting.
  4. [Composition]: Camera angle, lens choice (e.g., 85mm), and framing.
  5. [Color Palette]: Specific color tones and mood.
  6. [Fine Details]: Textures, skin details, jewelry reflections, fabric grain.
  7. [Quality Parameters]: Essential MJ parameters like --ar 9:16 --v 7.0 --style raw --stylize 250.

  The Negative Prompt should be comprehensive, targeting common AI artifacts, anatomical errors, and stylistic inconsistencies.

  Return the output in a clean JSON format with keys "positive" and "negative".`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { mimeType, data: base64 } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      temperature: 0.7,
    }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse MJ prompt JSON", e);
    return { 
      positive: "Professional fashion editorial, high-end photography, 8k resolution --ar 9:16 --v 7.0 --style raw", 
      negative: "low quality, distorted, bad anatomy, blurry, cartoonish" 
    };
  }
}

/**
 * Generates a fashion mix using gemini-3-pro-image-preview.
 */
export async function generateFashionMix(params: {
  faceImage?: string;
  poseImage?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
}): Promise<string> {
  const ai = getAIClient();

  const parts: any[] = [
    { text: `[System Instruction] 
    You are a world-class fashion photographer and digital compositor for luxury magazines like Vogue and Harper's Bazaar.

    GOAL: Create a photorealistic 2K fashion editorial image.

    CONSTRAINTS:
    1. FACE & HAIR: You MUST preserve the exact identity, facial features, and hairstyle of the model in the provided [FACE REFERENCE].
    2. POSE & ANGLE: You MUST match the body orientation, posture, and camera perspective of the [POSE REFERENCE].
    3. CLOTHING MIX: Seamlessly dress the model in the provided [CLOTHING ITEMS]. 
       - If some items are missing (e.g., no shoes uploaded), intelligently generate luxury items that perfectly complement the existing ones to create a complete, high-fashion outfit.
    4. STYLE: Ultra-detailed studio lighting, sharp focus, 8k resolution textures, sophisticated high-end aesthetic.
    5. COMPOSITION: Professional studio background unless specified otherwise. No watermarks or text.` }
  ];

  if (params.faceImage) {
    parts.push({ text: "--- [FACE & IDENTITY REFERENCE] ---" });
    parts.push({
      inlineData: {
        mimeType: params.faceImage.split(';')[0].split(':')[1],
        data: params.faceImage.split(',')[1]
      }
    });
  }

  if (params.poseImage) {
    parts.push({ text: "--- [POSE & COMPOSITION REFERENCE] ---" });
    parts.push({
      inlineData: {
        mimeType: params.poseImage.split(';')[0].split(':')[1],
        data: params.poseImage.split(',')[1]
      }
    });
  }

  params.clothingImages.forEach((img, idx) => {
    parts.push({ text: `--- [CLOTHING ITEM ${idx + 1}: ${img.type}] --- \nDescription: ${img.description}` });
    parts.push({
      inlineData: {
        mimeType: img.data.split(';')[0].split(':')[1],
        data: img.data.split(',')[1]
      }
    });
  });

  parts.push({ text: `[Final Creative Direction]: ${params.additionalPrompt || 'A high-end studio fashion editorial shot.'}` });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: {
      imageConfig: {
        aspectRatio: "9:16",
        imageSize: "2K"
      }
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image was generated.");
}

import React, { useState, useEffect } from 'react';
