import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing. Please select your API key first.");
  return new GoogleGenAI({ apiKey });
};

/**
 * Analyzes an image using gemini-3-flash to get a concise description for styling.
 */
export async function analyzeImage(base64Data: string, type: string): Promise<string> {
  const ai = getAIClient();
  const mimeType = base64Data.split(';')[0].split(':')[1];
  const base64 = base64Data.split(',')[1];

  const prompt = `Describe this fashion item or person reference for a high-end AI styling engine.
  Focus on:
  - Material textures (silk, wool, leather, etc.)
  - Precise colors and patterns
  - Fit and drape
  - Distinctive hardware or details
  Reference type: ${type}`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: {
      parts: [
        { inlineData: { mimeType, data: base64 } },
        { text: prompt }
      ]
    },
    config: {
      temperature: 0.1,
    }
  });

  return response.text || "No description.";
}

/**
 * Analyzes the FINAL generated image using Gemini 3 Pro to create a highly accurate Midjourney V7 prompt.
 */
export async function generateMidjourneyPromptFromImage(imageUrl: string): Promise<{ positive: string, negative: string }> {
  const ai = getAIClient();
  const mimeType = imageUrl.split(';')[0].split(':')[1];
  const base64 = imageUrl.split(',')[1];

  const prompt = `Act as a world-class Midjourney Prompt Engineer. 
  Analyze this generated fashion editorial image in detail and create a perfect Midjourney V7 prompt that would reproduce its exact aesthetic.

  The Positive Prompt MUST follow this strict sequence:
  1. [Subject]: Detailed description of the model, clothing, fabrics, and posture.
  2. [Style]: Artistic aesthetic, lighting type (e.g., hard shadows, soft box), and photographic style (e.g., high-end editorial).
  3. [Background]: Environment, props, and setting.
  4. [Composition]: Camera angle, lens choice (e.g., 85mm), and framing.
  5. [Color Palette]: Specific color tones and mood.
  6. [Fine Details]: Textures, skin details, jewelry reflections, fabric grain.
  7. [Quality Parameters]: Essential MJ parameters like --ar 3:4 --v 7.0 --style raw --stylize 250.

  The Negative Prompt should be comprehensive, targeting common AI artifacts, anatomical errors, and stylistic inconsistencies.

  Return the output in a clean JSON format with keys "positive" and "negative".`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: {
      parts: [
        { inlineData: { mimeType, data: base64 } },
        { text: prompt }
      ]
    },
    config: {
      responseMimeType: "application/json",
      temperature: 0.7,
    }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    console.error("Failed to parse MJ prompt JSON", e);
    return { 
      positive: "Professional fashion editorial, high-end photography, 8k resolution --ar 3:4 --v 7.0 --style raw", 
      negative: "low quality, distorted, bad anatomy, blurry, cartoonish" 
    };
  }
}

/**
 * Generates a fashion mix using gemini-3-pro-image-preview.
 */
export async function generateFashionMix(params: {
  faceImage?: string;
  poseImage?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
}): Promise<string> {
  const ai = getAIClient();

  const parts: any[] = [
    { text: `[System Instruction] 
    You are a world-class fashion photographer and digital compositor for luxury magazines like Vogue and Harper's Bazaar.

    GOAL: Create a photorealistic 2K fashion editorial image.

    CONSTRAINTS:
    1. FACE & HAIR: You MUST preserve the exact identity, facial features, and hairstyle of the model in the provided [FACE REFERENCE].
    2. POSE & ANGLE: You MUST match the body orientation, posture, and camera perspective of the [POSE REFERENCE].
    3. CLOTHING MIX: Seamlessly dress the model in the provided [CLOTHING ITEMS]. 
       - If some items are missing (e.g., no shoes uploaded), intelligently generate luxury items that perfectly complement the existing ones to create a complete, high-fashion outfit.
    4. STYLE: Ultra-detailed studio lighting, sharp focus, 8k resolution textures, sophisticated high-end aesthetic.
    5. COMPOSITION: Professional studio background unless specified otherwise. No watermarks or text.` }
  ];

  if (params.faceImage) {
    parts.push({ text: "--- [FACE & IDENTITY REFERENCE] ---" });
    parts.push({
      inlineData: {
        mimeType: params.faceImage.split(';')[0].split(':')[1],
        data: params.faceImage.split(',')[1]
      }
    });
  }

  if (params.poseImage) {
    parts.push({ text: "--- [POSE & COMPOSITION REFERENCE] ---" });
    parts.push({
      inlineData: {
        mimeType: params.poseImage.split(';')[0].split(':')[1],
        data: params.poseImage.split(',')[1]
      }
    });
  }

  params.clothingImages.forEach((img, idx) => {
    parts.push({ text: `--- [CLOTHING ITEM ${idx + 1}: ${img.type}] --- \nDescription: ${img.description}` });
    parts.push({
      inlineData: {
        mimeType: img.data.split(';')[0].split(':')[1],
        data: img.data.split(',')[1]
      }
    });
  });

  parts.push({ text: `[Final Creative Direction]: ${params.additionalPrompt || 'A high-end studio fashion editorial shot.'}` });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: {
      imageConfig: {
        aspectRatio: "3:4",
        imageSize: "2K"
      }
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }

  throw new Error("No image was generated.");
}

import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPromptFromImage } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(true);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPromptLoading, setIsPromptLoading] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }

    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생. API 키 설정을 확인하세요.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleDelete = (id: ImageSlotType) => {
    const resetSlot = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: null, description: '', isProcessing: false } : s);
    if (['face', 'pose'].includes(id)) setSlots(resetSlot);
    else setClothing(resetSlot);
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }

    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setMjPrompt(null);
    setResult(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '3:4' });

      // After image is generated, analyze it with Gemini 3 Pro to create the MJ prompt
      setIsPromptLoading(true);
      const prompts = await generateMidjourneyPromptFromImage(imageUrl);
      setMjPrompt(prompts);
      setIsPromptLoading(false);

      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("유료 API 키가 필요합니다. 다시 선택해주세요.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
      setIsPromptLoading(false);
    }
