                  <span className="text-[13px] font-black text-zinc-400 uppercase tracking-normal">
                    {isPromptLoading ? 'Analyzing Result...' : 'Structured Editorial Analysis'}
                  </span>
                </div>
                {mjPrompt && (
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(mjPrompt.positive);
                    }}
                    className="text-[10px] bg-zinc-900 hover:bg-zinc-800 px-4 py-2 rounded-xl text-zinc-400 font-bold uppercase transition-all active:scale-[0.95] border border-zinc-800 tracking-normal"
                  >
                    Copy
                  </button>
                )}
              </div>

              <div className="space-y-6">
                <div className="relative min-h-[100px]">
                  <label className="text-[10px] font-black text-zinc-600 uppercase block mb-3 tracking-normal">Positive Prompt</label>
                  {isPromptLoading ? (
                    <div className="absolute inset-0 flex items-center justify-center">
                      <div className="w-4 h-4 border-2 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin"></div>
                    </div>
                  ) : mjPrompt ? (
                    <p className="text-[11px] text-zinc-400 font-mono leading-relaxed bg-black p-4 rounded-2xl border border-zinc-900/50 tracking-normal whitespace-pre-wrap">
