import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPromptFromImage } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(true);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPromptLoading, setIsPromptLoading] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }

    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생. API 키 설정을 확인하세요.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleDelete = (id: ImageSlotType) => {
    const resetSlot = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: null, description: '', isProcessing: false } : s);
    if (['face', 'pose'].includes(id)) setSlots(resetSlot);
    else setClothing(resetSlot);
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }

    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setMjPrompt(null);
    setResult(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '3:4' });

      setIsPromptLoading(true);
      const prompts = await generateMidjourneyPromptFromImage(imageUrl);
      setMjPrompt(prompts);
      setIsPromptLoading(false);

      // Auto-scroll inside the right section if needed, though independent scroll is active
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("유료 API 키가 필요합니다. 다시 선택해주세요.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
      setIsPromptLoading(false);
    }
  };

  const isReadyToGenerate = !!slots.find(s => s.id === 'face')?.data;

  return (
    <div className="h-screen bg-black text-white font-['Inter'] flex flex-col tracking-normal overflow-hidden">
      <header className="py-6 px-6 bg-black border-b border-zinc-900/50 flex-shrink-0 z-30">
        <div className="max-w-[1800px] mx-auto flex flex-col items-center text-center">
          <div className="inline-flex items-center gap-3">
            <h1 className="text-[24px] font-bold tracking-normal leading-none">AI Fashion / Detailed Mix</h1>
            <span className="text-[9px] bg-indigo-600 px-2 py-0.5 rounded-full font-black uppercase tracking-normal">PRO</span>
          </div>
          <p className="text-zinc-600 text-[11px] font-bold uppercase tracking-normal mt-1 opacity-80">Studio Editorial Synthesis Engine</p>
        </div>
      </header>

      <main className="flex-grow overflow-hidden flex justify-center">
        <div className="max-w-[1800px] w-full grid grid-cols-1 lg:grid-cols-2 h-full">

          {/* Left Section (Scrollable) */}
          <section className="h-full overflow-y-auto p-6 lg:p-10 space-y-12 border-r border-zinc-900/50">
            <div className="space-y-6">
              <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">레퍼런스 이미지</h2>
              <div className="grid grid-cols-2 gap-8">
                {slots.map(slot => (
                  <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} onDelete={handleDelete} />
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">의상 / 아이템</h2>
              <div className="grid grid-cols-3 gap-6">
                {clothing.map(slot => (
                  <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} onDelete={handleDelete} />
                ))}
              </div>
            </div>

            <div className="space-y-6 pt-6 border-t border-zinc-900/30">
              <div className="space-y-2">
                <label className="text-[14px] font-bold text-[#ffffff] uppercase tracking-normal">Prompt 추가</label>
                <div className="bg-zinc-950 border border-zinc-900 rounded-2xl p-5 focus-within:border-zinc-700 transition-all">
                  <textarea
                    value={additionalPrompt}
                    onChange={(e) => setAdditionalPrompt(e.target.value)}
                    placeholder="분위기, 배경, 조명 등 세부 지시 사항을 입력하세요..."
                    className="w-full bg-transparent border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-800 resize-none h-24 text-sm tracking-normal leading-relaxed"
                  />
                </div>
              </div>

              <button
                onClick={handleGenerate}
                disabled={isGenerating}
                style={{ 
                  backgroundColor: (isGenerating || isReadyToGenerate) ? '#19ad55' : '#242b35',
                  fontSize: '16px',
                  letterSpacing: 'normal'
                }}
                className={`
                  w-full py-6 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl text-white tracking-normal
                  ${isGenerating ? 'cursor-not-allowed' : 'hover:opacity-90 active:scale-[0.99]'}
                `}
              >
                {isGenerating ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    GENERATING 2K...
                  </>
                ) : (
                  <>Generate Image(2K)</>
                )}
              </button>

              {error && (
                <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl text-red-400 text-[11px] font-bold tracking-normal text-center">
                  ⚠️ {error}
                </div>
              )}
            </div>
          </section>

          {/* Right Section (Scrollable) */}
          <section className="h-full overflow-y-auto bg-black p-6 lg:p-10 flex flex-col items-start justify-start">
            <div className="w-full flex flex-col gap-8 pb-10">
              <div className="flex items-center justify-between">
                <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">최종 이미지(2K)</h2>
                {result && (
                  <a
                    href={result.imageUrl}
                    download="fashion-editorial-2k.png"
                    className="flex items-center gap-2 text-[10px] font-bold text-zinc-500 hover:text-white transition-colors bg-zinc-900/50 px-3 py-1.5 rounded-lg border border-zinc-800"
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                    DOWNLOAD
                  </a>
                )}
              </div>

              <div className={`
                relative w-full aspect-[3/4] rounded-3xl border border-zinc-900 bg-zinc-950 overflow-hidden flex flex-col items-center justify-center shadow-2xl flex-shrink-0
                ${isGenerating ? 'ring-2 ring-[#19ad55]/20' : ''}
              `}>
                {result ? (
                  <div className="absolute inset-0 group bg-zinc-950">
                    <img src={result.imageUrl} alt="Final" className="w-full h-full object-contain" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center gap-4 backdrop-blur-[2px]">
                      <button 
                        onClick={() => setIsModalOpen(true)}
                        className="p-4 bg-white/10 hover:bg-white/20 rounded-full border border-white/20 text-white transition-all transform hover:scale-110 active:scale-95 shadow-xl"
                        title="확대보기"
                      >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" />
                        </svg>
                      </button>
                      <a
                        href={result.imageUrl}
                        download="fashion-editorial-2k.png"
                        className="p-4 bg-[#19ad55] hover:bg-[#158f46] rounded-full text-white transition-all transform hover:scale-110 active:scale-95 shadow-xl"
                        title="다운로드"
                      >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                      </a>
                    </div>
                  </div>
                ) : (
                  <div className="p-16 text-center space-y-6">
                    {isGenerating ? (
                      <div className="space-y-4">
                        <div className="w-12 h-12 border-2 border-[#19ad55] border-t-transparent rounded-full animate-spin mx-auto"></div>
                        <div className="space-y-1">
                          <p className="text-[#19ad55] text-[15.5px] font-black animate-pulse tracking-normal uppercase">Rendering High-Fidelity</p>
                          <p className="text-[11px] text-zinc-700 tracking-normal uppercase font-bold">Nano Banana Pro Image Engine</p>
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-4 opacity-10">
                        <svg className="w-20 h-20 text-zinc-500 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <p className="text-[13.5px] font-black text-zinc-500 tracking-normal uppercase">Studio Output Ready</p>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Midjourney Prompt Section */}
              <div className="space-y-6 p-8 bg-zinc-950/50 border border-zinc-900 rounded-[2rem] shadow-xl w-full flex-shrink-0">
                <div className="flex items-center justify-between border-b border-zinc-900 pb-4">
                  <div className="flex flex-col">
                    <h3 className="text-[10px] font-black text-indigo-500 uppercase tracking-normal">Midjourney V7 Prompt</h3>
                    <span className="text-[13px] font-black text-zinc-400 uppercase tracking-normal">
                      {isPromptLoading ? 'Analyzing Result...' : 'Structured Editorial Analysis'}
                    </span>
                  </div>
                  {mjPrompt && (
                    <button 
                      onClick={() => {
                        navigator.clipboard.writeText(mjPrompt.positive);
                      }}
                      className="text-[10px] bg-zinc-900 hover:bg-zinc-800 px-4 py-2 rounded-xl text-zinc-400 font-bold uppercase transition-all active:scale-[0.95] border border-zinc-800 tracking-normal"
                    >
                      Copy
                    </button>
                  )}
                </div>

                <div className="space-y-6">
                  <div className="relative min-h-[100px]">
                    <label className="text-[10px] font-black text-zinc-600 uppercase block mb-3 tracking-normal">Positive Prompt</label>
                    {isPromptLoading ? (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-4 h-4 border-2 border-indigo-500/30 border-t-indigo-500 rounded-full animate-spin"></div>
                      </div>
                    ) : mjPrompt ? (
                      <p className="text-[11px] text-zinc-400 font-mono leading-relaxed bg-black p-4 rounded-2xl border border-zinc-900/50 tracking-normal whitespace-pre-wrap">
                        {mjPrompt.positive}
                      </p>
                    ) : (
                      <div className="text-[11px] text-zinc-800 font-mono bg-black/20 p-4 rounded-2xl border border-dashed border-zinc-900/50 text-center py-10">
                        WAITING FOR GENERATION ANALYSIS...
                      </div>
                    )}
                  </div>

                  <div className="relative min-h-[80px]">
                    <label className="text-[10px] font-black text-red-900/40 uppercase block mb-3 tracking-normal">Negative Prompt</label>
                    {isPromptLoading ? (
                      <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-4 h-4 border-2 border-red-900/10 border-t-red-900/40 rounded-full animate-spin"></div>
                      </div>
                    ) : mjPrompt ? (
                      <p className="text-[11px] text-red-950/50 font-mono leading-relaxed bg-black/40 p-4 rounded-2xl border border-red-950/10 tracking-normal">
                        {mjPrompt.negative}
                      </p>
                    ) : (
                      <div className="text-[11px] text-red-950/10 font-mono bg-black/10 p-4 rounded-2xl border border-dashed border-red-950/5 text-center">
                        NOT AVAILABLE
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="mt-4 pt-8 border-t border-zinc-900/40 space-y-4 w-full">
                <h4 className="text-[11px] font-black uppercase text-zinc-600 tracking-normal">Generation Protocol</h4>
                <p className="text-[10.5px] text-zinc-700 leading-relaxed tracking-normal font-medium">
                  Identity preservation logic maintains face & hair characteristics. Anatomical posing strictly follows the pose reference. Midjourney Prompt is derived from direct visual analysis of the final result using Gemini 3 Pro Vision.
                </p>
              </div>
            </div>
          </section>

        </div>
      </main>

      {/* Zoom Modal */}
      {isModalOpen && result && (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-4">
          <button 
            onClick={() => setIsModalOpen(false)}
            className="absolute top-6 right-6 p-2 text-zinc-500 hover:text-white transition-colors"
          >
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

          <div className="w-full h-full max-w-[90vh] flex flex-col items-center justify-center gap-8">
            <img src={result.imageUrl} alt="Zoomed" className="max-w-full max-h-[80vh] object-contain rounded-xl shadow-2xl" />

            <a
              href={result.imageUrl}
              download="fashion-editorial-2k.png"
              className="flex items-center gap-3 bg-[#19ad55] text-white px-8 py-4 rounded-full font-black text-sm uppercase tracking-widest hover:bg-[#158f46] transition-all shadow-2xl active:scale-[0.95]"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              Download Full Image
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPromptFromImage } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
}

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(true);
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPromptLoading, setIsPromptLoading] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(selected);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = (error) => reject(error);
    });
  };

  const handleUpload = async (id: ImageSlotType, file: File) => {
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
    }

    const base64 = await fileToBase64(file);
    const update = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s);
    if (['face', 'pose'].includes(id)) setSlots(update);
    else setClothing(update);

    try {
      const description = await analyzeImage(base64, id);
      const finalize = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(finalize);
      else setClothing(finalize);
    } catch (err: any) {
      console.error(err);
      setError("이미지 분석 중 오류 발생. API 키 설정을 확인하세요.");
      const reset = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, isProcessing: false } : s);
      if (['face', 'pose'].includes(id)) setSlots(reset);
      else setClothing(reset);
    }
  };

  const handleDelete = (id: ImageSlotType) => {
    const resetSlot = (prev: ImageSlot[]) => prev.map(s => s.id === id ? { ...s, data: null, description: '', isProcessing: false } : s);
    if (['face', 'pose'].includes(id)) setSlots(resetSlot);
    else setClothing(resetSlot);
  };

  const handleGenerate = async () => {
    if (!slots.find(s => s.id === 'face')?.data) {
      setError("얼굴/헤어 레퍼런스는 필수입니다.");
      return;
    }

    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      await window.aistudio.openSelectKey();
      setApiKeySelected(true);
      return;
    }

    setIsGenerating(true);
    setError(null);
    setMjPrompt(null);
    setResult(null);

    try {
      const faceImage = slots.find(s => s.id === 'face')?.data || undefined;
      const poseImage = slots.find(s => s.id === 'pose')?.data || undefined;
      const clothingImages = clothing
        .filter(c => c.data)
        .map(c => ({ data: c.data!, description: c.description, type: c.label }));

      const imageUrl = await generateFashionMix({
        faceImage,
        poseImage,
        clothingImages,
        additionalPrompt
      });

      setResult({ imageUrl, aspectRatio: '3:4' });

      setIsPromptLoading(true);
      const prompts = await generateMidjourneyPromptFromImage(imageUrl);
      setMjPrompt(prompts);
      setIsPromptLoading(false);
    } catch (err: any) {
      console.error(err);
      if (err.message && err.message.includes("Requested entity was not found")) {
        setError("유료 API 키가 필요합니다. 다시 선택해주세요.");
        if (window.aistudio) await window.aistudio.openSelectKey();
      } else {
        setError(err.message || "생성 중 오류가 발생했습니다.");
      }
    } finally {
      setIsGenerating(false);
      setIsPromptLoading(false);
    }
  };

  const getFullPrompt = () => {
    if (!mjPrompt) return "";
    // Clean positive prompt from any parameters it might already have to append them at the end
    let pos = mjPrompt.positive.split('--')[0].trim();
    let params = mjPrompt.positive.match(/--[a-z0-9 ]+/g)?.join(' ') || "--ar 3:4 --v 7 --stylize 300";
    let neg = mjPrompt.negative ? `--no ${mjPrompt.negative.replace(/,/g, '')}` : "";
    return `${pos} ${neg} ${params}`.replace(/\s+/g, ' ').trim();
  };

  const handleCopyPrompt = () => {
    const prompt = getFullPrompt();
    if (prompt) {
      navigator.clipboard.writeText(prompt);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const isReadyToGenerate = !!slots.find(s => s.id === 'face')?.data;

  return (
    <div className="h-screen bg-black text-white font-['Inter'] flex flex-col tracking-normal overflow-hidden">
      <header className="py-6 px-6 bg-black border-b border-zinc-900/50 flex-shrink-0 z-30">
        <div className="max-w-[1800px] mx-auto flex flex-col items-center text-center">
          <div className="inline-flex items-center gap-3">
            <h1 className="text-[24px] font-bold tracking-normal leading-none">AI Fashion / Detailed Mix</h1>
            <span className="text-[9px] bg-indigo-600 px-2 py-0.5 rounded-full font-black uppercase tracking-normal">PRO</span>
          </div>
          <p className="text-zinc-600 text-[11px] font-bold uppercase tracking-normal mt-1 opacity-80">Studio Editorial Synthesis Engine</p>
        </div>
      </header>

      <main className="flex-grow overflow-hidden flex justify-center">
        <div className="max-w-[1800px] w-full grid grid-cols-1 lg:grid-cols-2 h-full">

          {/* Left Section (Scrollable) */}
          <section className="h-full overflow-y-auto p-6 lg:p-10 space-y-12 border-r border-zinc-900/50">
            <div className="space-y-6">
              <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">레퍼런스 이미지</h2>
              <div className="grid grid-cols-2 gap-8">
                {slots.map(slot => (
                  <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} onDelete={handleDelete} />
                ))}
              </div>
            </div>

            <div className="space-y-6">
              <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">의상 / 아이템</h2>
              <div className="grid grid-cols-3 gap-6">
                {clothing.map(slot => (
                  <ImageUpload key={slot.id} {...slot} onUpload={handleUpload} onDelete={handleDelete} />
                ))}
              </div>
            </div>

            <div className="space-y-6 pt-6 border-t border-zinc-900/30">
              <div className="space-y-2">
                <label className="text-[14px] font-bold text-[#ffffff] uppercase tracking-normal">Prompt 추가</label>
                <div className="bg-zinc-950 border border-zinc-900 rounded-2xl p-5 focus-within:border-zinc-700 transition-all">
                  <textarea
                    value={additionalPrompt}
                    onChange={(e) => setAdditionalPrompt(e.target.value)}
                    placeholder="분위기, 배경, 조명 등 세부 지시 사항을 입력하세요..."
                    className="w-full bg-transparent border-none focus:ring-0 text-zinc-300 placeholder:text-zinc-800 resize-none h-24 text-sm tracking-normal leading-relaxed"
                  />
                </div>
              </div>

              <button
                onClick={handleGenerate}
                disabled={isGenerating}
                style={{ 
                  backgroundColor: (isGenerating || isReadyToGenerate) ? '#19ad55' : '#242b35',
                  fontSize: '16px',
                  letterSpacing: 'normal'
                }}
                className={`
                  w-full py-6 rounded-2xl font-black flex items-center justify-center gap-3 transition-all shadow-xl text-white tracking-normal
                  ${isGenerating ? 'cursor-not-allowed' : 'hover:opacity-90 active:scale-[0.99]'}
                `}
              >
                {isGenerating ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                    GENERATING 2K...
                  </>
                ) : (
                  <>Generate Image(2K)</>
                )}
              </button>

              {error && (
                <div className="p-4 bg-red-500/5 border border-red-500/20 rounded-xl text-red-400 text-[11px] font-bold tracking-normal text-center">
                  ⚠️ {error}
                </div>
              )}
            </div>
          </section>

          {/* Right Section (Scrollable) */}
          <section className="h-full overflow-y-auto bg-black p-6 lg:p-10 flex flex-col items-start justify-start">
            <div className="w-full flex flex-col gap-8 pb-10">
              <div className="flex items-center justify-between">
                <h2 className="text-[14px] font-black text-[#ffffff] uppercase tracking-normal">최종 이미지(2K)</h2>
                {result && (
                  <a
                    href={result.imageUrl}
                    download="fashion-editorial-2k.png"
                    className="flex items-center gap-2 text-[10px] font-bold text-zinc-500 hover:text-white transition-colors bg-zinc-900/50 px-3 py-1.5 rounded-lg border border-zinc-800"
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                    </svg>
                    DOWNLOAD
                  </a>
                )}
              </div>

              <div className={`
                relative w-full aspect-[3/4] rounded-3xl border border-zinc-900 bg-zinc-950 overflow-hidden flex flex-col items-center justify-center shadow-2xl flex-shrink-0
                ${isGenerating ? 'ring-2 ring-[#19ad55]/20' : ''}
              `}>
                {result ? (
                  <div className="absolute inset-0 group bg-zinc-950">
                    <img src={result.imageUrl} alt="Final" className="w-full h-full object-contain" />
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-all duration-300 flex items-center justify-center gap-4 backdrop-blur-[2px]">
                      <button 
                        onClick={() => setIsModalOpen(true)}
                        className="p-4 bg-white/10 hover:bg-white/20 rounded-full border border-white/20 text-white transition-all transform hover:scale-110 active:scale-95 shadow-xl"
                        title="확대보기"
                      >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0zM10 7v3m0 0v3m0-3h3m-3 0H7" />
                        </svg>
                      </button>
                      <a
                        href={result.imageUrl}
                        download="fashion-editorial-2k.png"
                        className="p-4 bg-[#19ad55] hover:bg-[#158f46] rounded-full text-white transition-all transform hover:scale-110 active:scale-95 shadow-xl"
                        title="다운로드"
                      >
                        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                        </svg>
                      </a>
                    </div>
                  </div>
                ) : (
                  <div className="p-16 text-center space-y-6">
                    {isGenerating ? (
                      <div className="space-y-4">
                        <div className="w-12 h-12 border-2 border-[#19ad55] border-t-transparent rounded-full animate-spin mx-auto"></div>
                        <div className="space-y-1">
                          <p className="text-[#19ad55] text-[15.5px] font-black animate-pulse tracking-normal uppercase">Rendering High-Fidelity</p>
                          <p className="text-[11px] text-zinc-700 tracking-normal uppercase font-bold">Nano Banana Pro Image Engine</p>
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-4 opacity-10">
                        <svg className="w-20 h-20 text-zinc-500 mx-auto" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                        </svg>
                        <p className="text-[13.5px] font-black text-zinc-500 tracking-normal uppercase">Studio Output Ready</p>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Midjourney Prompt Section - Updated Design */}
              <div className="flex flex-col gap-4 w-full flex-shrink-0">
                <h3 className="text-[14px] font-black text-[#19ad55] uppercase tracking-normal">
                  AI GENERATED MIDJOURNEY V7 PROMPT
                </h3>

                <div className="relative group bg-[#020617] border border-zinc-900 rounded-xl overflow-hidden shadow-xl min-h-[140px] flex flex-col">
                  {/* Header / Copy Button Area */}
                  <div className="flex justify-end p-4 pb-0 z-10">
                    <button 
                      onClick={handleCopyPrompt}
                      disabled={isPromptLoading || !mjPrompt}
                      className={`
                        flex items-center gap-2 px-4 py-2.5 rounded-lg font-black text-[12px] uppercase transition-all active:scale-95 shadow-lg
                        ${copySuccess ? 'bg-[#19ad55] text-white' : 'bg-[#19ad55] hover:bg-[#158f46] text-white'}
                        ${(isPromptLoading || !mjPrompt) ? 'opacity-30 cursor-not-allowed' : ''}
                      `}
                    >
                      {copySuccess ? (
                        <>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                          </svg>
                          PROMPT COPIED
                        </>
                      ) : (
                        <>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 16H6a2 2 0 01-2-2V6a2 2 0 012-2h8a2 2 0 012 2v2m-6 12h8a2 2 0 002-2v-8a2 2 0 00-2-2h-8a2 2 0 00-2 2v8a2 2 0 002 2z" />
                          </svg>
                          COPY AI PROMPT
                        </>
                      )}
                    </button>
                  </div>

                  {/* Content Area */}
                  <div className="p-6 pt-2">
                    {isPromptLoading ? (
                      <div className="flex flex-col items-center justify-center py-10 gap-3">
                        <div className="w-5 h-5 border-2 border-[#19ad55]/30 border-t-[#19ad55] rounded-full animate-spin"></div>
                        <span className="text-[11px] font-bold text-zinc-600 uppercase tracking-widest">Generating Prompt...</span>
                      </div>
                    ) : mjPrompt ? (
                      <div className="relative">
                        <pre className="text-[15px] text-zinc-300 font-mono leading-relaxed tracking-tight whitespace-pre-wrap break-words">
                          {getFullPrompt()}
                        </pre>
                      </div>
                    ) : (
                      <div className="flex items-center justify-center py-12">
                        <span className="text-[11px] font-black text-zinc-800 uppercase tracking-widest text-center">
                          Awaiting Studio Output for Analysis
                        </span>
                      </div>
                    )}
                  </div>
                </div>
              </div>

              <div className="mt-4 pt-8 border-t border-zinc-900/40 space-y-4 w-full">
                <h4 className="text-[11px] font-black uppercase text-zinc-600 tracking-normal">Generation Protocol</h4>
                <p className="text-[10.5px] text-zinc-700 leading-relaxed tracking-normal font-medium">
                  Identity preservation logic maintains face & hair characteristics. Anatomical posing strictly follows the pose reference. Midjourney Prompt is derived from direct visual analysis of the final result using Gemini 3 Pro Vision.
                </p>
              </div>
            </div>
          </section>

        </div>
      </main>

      {/* Zoom Modal */}
      {isModalOpen && result && (
        <div className="fixed inset-0 z-50 bg-black/95 flex flex-col items-center justify-center p-4">
          <button 
            onClick={() => setIsModalOpen(false)}
            className="absolute top-6 right-6 p-2 text-zinc-500 hover:text-white transition-colors"
          >
            <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>

