{
  "name": "AI Fashion / Detailed Mix PRO",
  "description": "High-end fashion editorial generator using Gemini 3 Pro with distinct face, pose, and clothing reference capabilities.",
  "requestFramePermissions": []
}

export type ImageSlotType = 'face' | 'pose' | 'outer' | 'top' | 'bottom' | 'shoes' | 'accessory';

export interface ImageSlot {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
}

export interface GenerationResult {
  imageUrl: string;
  aspectRatio: string;
}

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API Key is missing.");
  return new GoogleGenAI({ apiKey });
};

export async function analyzeImage(base64Data: string, type: string): Promise<string> {
  const ai = getAIClient();
  const mimeType = base64Data.split(';')[0].split(':')[1];
  const base64 = base64Data.split(',')[1];

  const prompt = `Describe this fashion item or person reference for a high-end AI styling engine. Focus on textures, colors, fit, and distinctive details. Type: ${type}`;

  const response: GenerateContentResponse = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: { parts: [{ inlineData: { mimeType, data: base64 } }, { text: prompt }] },
    config: { temperature: 0.1 }
  });

  return response.text || "No description.";
}

export async function generateMidjourneyPromptFromImage(imageUrl: string): Promise<{ positive: string, negative: string }> {
  const ai = getAIClient();
  const mimeType = imageUrl.split(';')[0].split(':')[1];
  const base64 = imageUrl.split(',')[1];

  const prompt = `Act as a world-class Midjourney Prompt Engineer. Analyze this fashion image and create a perfect MJ V7 prompt. Return as JSON with "positive" and "negative" keys. Include --ar 3:4 --v 7.0 --stylize 300.`;

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-preview',
    contents: { parts: [{ inlineData: { mimeType, data: base64 } }, { text: prompt }] },
    config: { responseMimeType: "application/json", temperature: 0.7 }
  });

  try {
    return JSON.parse(response.text || '{}');
  } catch (e) {
    return { positive: "High-end fashion editorial --ar 3:4 --v 7.0", negative: "low quality" };
  }
}

export async function generateFashionMix(params: {
  faceImage?: string;
  poseImage?: string;
  clothingImages: { data: string; description: string; type: string }[];
  additionalPrompt: string;
}): Promise<string> {
  const ai = getAIClient();
  const parts: any[] = [{ text: "System: Preserve [FACE REFERENCE] identity, [POSE REFERENCE] anatomy, and synthesize [CLOTHING ITEMS]." }];

  if (params.faceImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.faceImage.split(',')[1] } });
  if (params.poseImage) parts.push({ inlineData: { mimeType: 'image/png', data: params.poseImage.split(',')[1] } });

  params.clothingImages.forEach(img => {
    parts.push({ text: `Item: ${img.type}, Description: ${img.description}` });
    parts.push({ inlineData: { mimeType: 'image/png', data: img.data.split(',')[1] } });
  });

  parts.push({ text: params.additionalPrompt || "High-end studio fashion editorial." });

  const response = await ai.models.generateContent({
    model: 'gemini-3-pro-image-preview',
    contents: { parts },
    config: { imageConfig: { aspectRatio: "3:4", imageSize: "2K" } }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
  }
  throw new Error("Generation failed.");
}

import React, { useState } from 'react';
import { ImageSlotType } from '../types';

interface ImageUploadProps {
  id: ImageSlotType;
  label: string;
  data: string | null;
  description: string;
  isProcessing: boolean;
  onUpload: (id: ImageSlotType, file: File) => void;
  onDelete: (id: ImageSlotType) => void;
}

const ImageUpload: React.FC<ImageUploadProps> = ({ id, label, data, description, isProcessing, onUpload, onDelete }) => {
  const [isDragging, setIsDragging] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) onUpload(id, file);
  };

  return (
    <div className="flex flex-col gap-2 w-full">
      <span className="text-[11px] font-bold text-[#ffffff] uppercase tracking-normal opacity-80">{label}</span>
      <div 
        className={`relative flex flex-col items-center justify-center w-full aspect-square rounded-xl border border-dashed transition-all overflow-hidden ${data ? 'border-indigo-500 bg-zinc-950' : 'border-zinc-800 bg-black'}`}
        onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => { e.preventDefault(); setIsDragging(false); const file = e.dataTransfer.files?.[0]; if (file) onUpload(id, file); }}
      >
        <label className="absolute inset-0 cursor-pointer">
          <input type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
        </label>
        {data ? (
          <>
            <img src={data} alt={label} className="w-full h-full object-contain pointer-events-none" />
            <button onClick={(e) => { e.preventDefault(); e.stopPropagation(); onDelete(id); }} className="absolute top-2 right-2 p-1.5 bg-black/60 hover:bg-red-600 text-white rounded-lg border border-white/10 z-10">
              <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
            </button>
          </>
        ) : (
          <div className="flex flex-col items-center text-center p-10 opacity-40">
            <svg className="w-8 h-8 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M12 6v12m6-6H6" /></svg>
            <p className="text-[10px] font-bold uppercase tracking-widest">Upload</p>
          </div>
        )}
        {isProcessing && (
          <div className="absolute inset-0 bg-black/80 flex items-center justify-center backdrop-blur-sm z-20">
            <div className="w-5 h-5 border border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
          </div>
        )}
      </div>
      {description && !isProcessing && <div className="text-[9px] text-zinc-600 line-clamp-1 italic px-1">{description}</div>}
    </div>
  );
};

export default ImageUpload;

import React, { useState, useEffect } from 'react';
import { ImageSlot, ImageSlotType, GenerationResult } from './types';
import { analyzeImage, generateFashionMix, generateMidjourneyPromptFromImage } from './services/geminiService';
import ImageUpload from './components/ImageUpload';

const INITIAL_SLOTS: ImageSlot[] = [
  { id: 'face', label: '얼굴/헤어 레퍼런스', data: null, description: '', isProcessing: false },
  { id: 'pose', label: '포즈 레퍼런스', data: null, description: '', isProcessing: false },
];

const CLOTHING_SLOTS: ImageSlot[] = [
  { id: 'outer', label: '아우터', data: null, description: '', isProcessing: false },
  { id: 'top', label: '상의', data: null, description: '', isProcessing: false },
  { id: 'bottom', label: '하의', data: null, description: '', isProcessing: false },
  { id: 'shoes', label: '신발', data: null, description: '', isProcessing: false },
  { id: 'accessory', label: '악세서리', data: null, description: '', isProcessing: false },
];

export default function App() {
  const [slots, setSlots] = useState<ImageSlot[]>(INITIAL_SLOTS);
  const [clothing, setClothing] = useState<ImageSlot[]>(CLOTHING_SLOTS);
  const [additionalPrompt, setAdditionalPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [isPromptLoading, setIsPromptLoading] = useState(false);
  const [result, setResult] = useState<GenerationResult | null>(null);
  const [mjPrompt, setMjPrompt] = useState<{ positive: string, negative: string } | null>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  const handleUpload = async (id: ImageSlotType, file: File) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = async () => {
      const base64 = reader.result as string;
      const setter = ['face', 'pose'].includes(id) ? setSlots : setClothing;
      setter(prev => prev.map(s => s.id === id ? { ...s, data: base64, isProcessing: true } : s));
      const description = await analyzeImage(base64, id);
      setter(prev => prev.map(s => s.id === id ? { ...s, description, isProcessing: false } : s));
    };
  };

  const handleGenerate = async () => {
    setIsGenerating(true);
    try {
      const face = slots.find(s => s.id === 'face')?.data || '';
      const pose = slots.find(s => s.id === 'pose')?.data || '';
      const cImages = clothing.filter(c => c.data).map(c => ({ data: c.data!, description: c.description, type: c.label }));
      const imageUrl = await generateFashionMix({ faceImage: face, poseImage: pose, clothingImages: cImages, additionalPrompt });
      setResult({ imageUrl, aspectRatio: '3:4' });
      setIsPromptLoading(true);
      const mjp = await generateMidjourneyPromptFromImage(imageUrl);
      setMjPrompt(mjp);
    } finally {
      setIsGenerating(false);
      setIsPromptLoading(false);
    }
  };

  const fullMJ = mjPrompt ? `${mjPrompt.positive} --no ${mjPrompt.negative}` : "";

  return (
    <div className="min-h-screen bg-black text-white">
      <header className="p-8 border-b border-zinc-900 text-center">
        <h1 className="text-[36px] font-bold">AI Fashion / Detailed Mix</h1>
        <p className="text-zinc-600 text-[11px] uppercase tracking-widest mt-2">Studio Editorial Synthesis Engine</p>
      </header>

      <main className="max-w-[1800px] mx-auto grid grid-cols-1 lg:grid-cols-2 gap-0">
        {/* Left Panel */}
        <section className="p-10 border-r border-zinc-900 space-y-12">
          <div className="space-y-6">
            <h2 className="text-[14px] font-black uppercase">References</h2>
            <div className="grid grid-cols-2 gap-6">{slots.map(s => <ImageUpload key={s.id} {...s} onUpload={handleUpload} onDelete={(id) => setSlots(p => p.map(x => x.id === id ? {...x, data: null} : x))} />)}</div>
          </div>
          <div className="space-y-6">
            <h2 className="text-[14px] font-black uppercase">Clothing Items</h2>
            <div className="grid grid-cols-3 gap-4">{clothing.map(c => <ImageUpload key={c.id} {...c} onUpload={handleUpload} onDelete={(id) => setClothing(p => p.map(x => x.id === id ? {...x, data: null} : x))} />)}</div>
          </div>
          <button onClick={handleGenerate} className="w-full py-6 bg-[#19ad55] rounded-2xl font-black text-[16px] hover:opacity-90">
            {isGenerating ? "GENERATING 2K..." : "Generate Image(2K)"}
          </button>
        </section>

        {/* Right Panel */}
        <section className="p-10 space-y-10">
          <h2 className="text-[14px] font-black uppercase">Studio Output</h2>
          <div className="aspect-[3/4] bg-zinc-950 rounded-3xl border border-zinc-900 overflow-hidden relative">
            {result ? <img src={result.imageUrl} className="w-full h-full object-contain" /> : <div className="h-full flex items-center justify-center opacity-10">Awaiting Signal</div>}
          </div>

          <div className="space-y-4">
            <h3 className="text-[14px] font-black">Ai Generated Midjourney V7</h3>
            <div className="bg-[#020617] border border-zinc-900 rounded-xl p-6 relative">
              <div className="flex justify-end mb-4">
                <button 
                  onClick={() => { navigator.clipboard.writeText(fullMJ); setCopySuccess(true); setTimeout(() => setCopySuccess(false), 2000); }}
                  className="w-[110px] h-[36px] bg-[#19ad55] rounded-lg text-[12px] font-bold"
                >
                  {copySuccess ? "Copied!" : "Copy Prompt"}
                </button>
              </div>
              <pre className="text-[12px] text-zinc-300 font-mono whitespace-pre-wrap">{isPromptLoading ? "Analyzing visual data..." : fullMJ || "Awaiting results..."}</pre>
            </div>
          </div>
        </section>
      </main>
    </div>
  );
}
